import {eggCapacity,validatePouch} from './egg-pouch.js?v=0.90.36';
import {prepareBreedingEffects,validBreedingEffects,validateNurseryItems} from './breeding-items.js?v=0.90.35';
import {rollShiny} from './shinies.js?v=0.90.20';
import {rollInheritance,validateInheritance,availableProdigyStats} from './breeding-inheritance.js?v=0.90.35';
import {DATA} from './data.js?v=0.87.0';
import {rootForm} from './route-roster.js?v=0.87.0';
import {inheritedGrowthBonus,hashSeed} from './progression.js?v=0.90.18';
export const EGG_ICON='assets/items/abyssal-egg.webp';
export const BREEDING_FEE=1000,EGG_STEPS=512,EGG_CAPACITY=3;
const protectedFamilies=new Set(DATA.species.filter(s=>s.legendaryRoamer||/legendary|mythic/i.test(s.power_class||'')||/^(mythic|mythical|legendary)$/i.test(s.role||'')).map(s=>rootForm(s.id)));

export function nurseryState(state){state.nursery??={version:1,serial:0,eggs:[],hatched:[]};return state.nursery;}
export function breedingUnlocked(state){return !!state.fates?.['LDR-02']||!!state.sideCampaigns?.marchMeadow?.claimed;}
export function breedable(unit){const s=unit?.species;return !!s&&unit.hp>0&&!unit.dead&&!protectedFamilies.has(rootForm(s.id))&&!s.legendaryRoamer&&!(/legendary|mythic/i.test(s.power_class||'')||[s.role,s.rarity].some(v=>/^(mythic|mythical|legendary)$/i.test(v||'')));}
export function breedingPair(a,b){if(!a||!b||a.uid===b.uid)return {ok:false,reason:'Choose two different living partners.'};if(!breedable(a)||!breedable(b))return {ok:false,reason:'One-of-a-kind and mythic Abyssals cannot breed.'};const shared=a.species.types.filter(t=>b.species.types.includes(t));if(!shared.length)return {ok:false,reason:'The parents must share at least one type.'};return {ok:true,shared,forms:[rootForm(a.species.id),rootForm(b.species.id)]};}
const partners=s=>[...(s.party||[]),...(s.reserve||[])];
export function createBreedingEgg(state,aUid,bUid,{random=null,inheritancePlans=[],breedingOptions={}}={}){const n=nurseryState(state),a=partners(state).find(u=>u.uid===aUid),b=partners(state).find(u=>u.uid===bUid),pair=breedingPair(a,b);if(!breedingUnlocked(state)||!pair.ok||n.eggs.length>=eggCapacity(state)||!(state.money>=BREEDING_FEE))return null;
 const setup=prepareBreedingEffects(state,breedingOptions,pair.forms);if(!setup.ok)return null;
 const serial=n.serial+1,seed=hashSeed(`${state.playerName||'Aimon'}:egg:${serial}:${[aUid,bUid].sort().join(':')}`),roll=random?random():hashSeed(seed+':parent')/4294967296,index=setup.effects.sealParent??(roll<.5?0:1),parent=[a,b][index],species=DATA.species.find(s=>s.id===pair.forms[index]);if(!species)return null;
 const abilitySlot=parent.abilitySlot==='hidden'&&parent.hiddenAbilityUnlocked&&species.ability_names?.hidden?'hidden':parent.abilitySlot==='secondary'&&species.ability_names?.secondary?'secondary':'primary';
 if(setup.effects.enhancer==='thread'&&!availableProdigyStats(species,[a,b][1-index],parent,inheritancePlans[index]).includes(setup.effects.threadStat))return null;
 let inheritanceRoll=0;
 const donorIndex=1-index,inheritance=rollInheritance(species,[a,b][donorIndex],donorIndex,inheritancePlans[index],random||(()=>hashSeed(seed+':inheritance:'+inheritanceRoll++)/4294967296),parent,setup.effects);if(!inheritance)return null;
 const shiny=rollShiny(()=>hashSeed(seed+':shiny')/4294967296,{bred:true});
 const egg={shiny,inheritance,id:'egg-'+serial,serial,seed,speciesId:species.id,parents:[aUid,bUid],parentSpecies:[a.species.id,b.species.id],selectedParent:index,abilitySlot,remaining:setup.total,total:setup.total,breedingEffects:setup.effects};state.money-=BREEDING_FEE;for(const id of setup.used)state.nurseryItems[id]--;n.serial=serial;n.eggs.push(egg);return egg;
}
export function advanceEggSteps(state){const ready=[];for(const egg of state.nursery?.eggs||[])if(egg.remaining>0){egg.remaining--;if(egg.remaining===0)ready.push(egg.id);}return ready;}
export function hatchBreedingEgg(state,id,create){const n=nurseryState(state),egg=n.eggs.find(e=>e.id===id);if(!egg||egg.remaining!==0||typeof create!=='function'||n.hatched.some(e=>e.id===id))return null;const species=DATA.species.find(s=>s.id===egg.speciesId);if(!species||protectedFamilies.has(rootForm(species.id))||(/legendary|mythic/i.test(species.power_class||'')||/^(mythic|mythical|legendary)$/i.test(species.role||''))||species.legendaryRoamer||rootForm(species.id)!==species.id)return null;
 const u=create(species.id,1,'hatched:'+egg.id+':'+egg.seed);if(!u||u.level!==1||u.species.id!==egg.speciesId)return null;u.shiny=egg.shiny===true;u.originalStarter=false;u.lives=1;u.growthMultiplier=1;u.giftOrigin='Nursery egg';u.abilitySlot=egg.abilitySlot;if(egg.abilitySlot==='hidden')u.hiddenAbilityUnlocked=true;if(egg.inheritance){validateInheritance(egg.inheritance,species,egg.selectedParent);u.breedingInheritance=structuredClone(egg.inheritance);if(egg.inheritance.moveId!==null){const m=DATA.moves.find(m=>m.id===egg.inheritance.moveId);u.moves=[...u.moves.filter(v=>v.id!==m.id).slice(0,3),{...m,left:m.pp}];}}u.birth={kind:'egg',parents:[...egg.parents],parentSpecies:[...egg.parentSpecies],seed:egg.seed};(state.party.length<6?state.party:state.reserve).push(u);n.eggs=n.eggs.filter(e=>e.id!==id);n.hatched.push({id,uid:u.uid,speciesId:species.id});return u;
}
export function validateNurserySnapshot(state){validateNurseryItems(state);validatePouch(state);const n=state.nursery;if(n===undefined)return true;if(!n||n.version!==1||!Number.isSafeInteger(n.serial)||n.serial<0||!Array.isArray(n.eggs)||n.eggs.length>eggCapacity(state)||!Array.isArray(n.hatched)||n.hatched.length>2000)throw Error('The nursery record is invalid.');const ids=new Set();for(const e of n.eggs){const s=DATA.species.find(s=>s.id===e?.speciesId);if(!e||typeof e.id!=='string'||ids.has(e.id)||!Number.isSafeInteger(e.serial)||e.serial<1||e.serial>n.serial||e.id!=='egg-'+e.serial||!Number.isSafeInteger(e.seed)||e.seed<1||e.seed>4294967295||!Number.isInteger(e.remaining)||e.remaining<0||e.remaining>e.total||(e.breedingEffects===undefined?e.total!==EGG_STEPS:!validBreedingEffects(e.breedingEffects)||e.total!==(e.breedingEffects.warmer?384:512)||e.breedingEffects.sealParent!==null&&e.breedingEffects.sealParent!==e.selectedParent)||![0,1].includes(e.selectedParent)||!Array.isArray(e.parents)||e.parents.length!==2||e.parents.some(id=>typeof id!=='string'||id.length>300)||e.parents[0]===e.parents[1]||!Array.isArray(e.parentSpecies)||e.parentSpecies.length!==2||e.parentSpecies.some(id=>!DATA.species.some(s=>s.id===id))||!s||protectedFamilies.has(rootForm(s.id))||rootForm(s.id)!==s.id||rootForm(e.parentSpecies[e.selectedParent])!==s.id||s.legendaryRoamer||(/legendary|mythic/i.test(s.power_class||'')||/^(mythic|mythical|legendary)$/i.test(s.role||''))||!['primary','secondary','hidden'].includes(e.abilitySlot)||!s.ability_names?.[e.abilitySlot])throw Error('An egg record is invalid.');if(e.shiny!==undefined&&typeof e.shiny!=='boolean')throw Error('An egg shiny record is invalid.');validateInheritance(e.inheritance,s,e.selectedParent);ids.add(e.id);}for(const e of n.hatched)if(!e||typeof e.id!=='string'||typeof e.uid!=='string'||!DATA.species.some(s=>s.id===e.speciesId)||ids.has(e.id))throw Error('A hatchling record is invalid.');else ids.add(e.id);return true;}

